use std::marker::PhantomData;
struct Locked;
struct Unlocked;
struct Door<S> { _state: PhantomData<S> }
impl Door<Locked> {
    fn new() -> Self { Door { _state: PhantomData } }
    fn unlock(self) -> Door<Unlocked> { println!("Unlocked"); Door { _state: PhantomData } }
}
impl Door<Unlocked> {
    fn open(&self) { println!("Opened"); }
}
fn main() {
    let d = Door::<Locked>::new();
    let d = d.unlock();
    d.open();
}

